package api

import (
	"html/template"
	"net/http"

	"github.com/joaoteixeira10/orbit/api/docs"

	"github.com/gin-gonic/gin"
)

// The API reference: Scalar (https://scalar.com) over the OpenAPI document
// generated by swag (`make swag`). Scalar's script is bundled with the page
// and served from this origin (/scalar/standalone.js), so the CSP stays
// script-src 'self' and nothing loads from a CDN.
var docsPage = template.Must(template.New("docs").Parse(`<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="referrer" content="no-referrer">
<title>Orbit API</title>
</head>
<body>
<script id="api-reference" data-url="/api/v1/openapi.json" data-configuration="{{.}}"></script>
<script src="/scalar/standalone.js"></script>
</body>
</html>`))

// Scalar settings: no external fonts, none of Scalar's hosted features (AI
// agent, MCP, the developer toolbar with Share / Deploy), Orbit's colours.
const scalarConfig = `{"withDefaultFonts":false,"agent":{"disabled":true},"mcp":{"disabled":true},"showDeveloperTools":"never",` +
	`"metaData":{"title":"Orbit API"},` +
	`"customCss":":root{--scalar-font:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;--scalar-font-code:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace}` +
	`.light-mode{--scalar-color-accent:#2463eb;--scalar-background-1:#fff;--scalar-background-2:#f7f8fa;--scalar-background-3:#eef0f3;--scalar-border-color:#dde1e6}` +
	`.dark-mode{--scalar-color-accent:#5b9bff;--scalar-background-1:#14171c;--scalar-background-2:#101318;--scalar-background-3:#0b0d10;--scalar-border-color:#252a32}"}`

// apiDocs serves the API reference page.
func (h *Handlers) apiDocs(c *gin.Context) {
	c.Header("Content-Type", "text/html; charset=utf-8")
	c.Status(http.StatusOK)
	_ = docsPage.Execute(c.Writer, scalarConfig)
}

// openAPI serves the OpenAPI document the reference is built from.
func (h *Handlers) openAPI(c *gin.Context) {
	c.Data(http.StatusOK, "application/json; charset=utf-8", []byte(docs.SwaggerInfo.ReadDoc()))
}
